(() => {
'use strict';
const D=window.TPC_DATA;
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const currency=n=>new Intl.NumberFormat('cs-CZ',{style:'currency',currency:'CZK',maximumFractionDigits:0}).format(n);
const img=(src,alt='',cls='',eager=false)=>`<img src="${esc(src)}" alt="${esc(alt)}" class="${cls}" ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async">`;
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">${({lock:'<rect x="5" y="10" width="14" height="11" rx="1"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/><path d="M12 14v3"/>',book:'<path d="M12 5c-3-2-7-2-10 0v15c3-2 7-2 10 0 3-2 7-2 10 0V5c-3-2-7-2-10 0Z"/><path d="M12 5v15"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>',grid:'<path d="M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z"/>',order:'<path d="M6 2h12v20l-3-2-3 2-3-2-3 2V2Z"/><path d="M9 7h6M9 11h6M9 15h4"/>',check:'<path d="m5 12 4 4L19 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',logout:'<path d="M10 3H4v18h6M13 7l5 5-5 5M8 12h13"/>',chart:'<path d="M4 3v18h18M8 17v-5M13 17V8M18 17V4"/>'})[name]||''}</svg>`;
const BOOKS=[
{id:'prep',title:'Soutěžní příprava od A do Z',short:'Soutěžní příprava',line1:'CESTA NA',line2:'PÓDIUM.',category:'Soutěžní příprava',price:890,pages:148,volume:'01',image:D.coaches[0].image,accent:'#c6a675',summary:'Od prvního rozhodnutí až po poslední pózu. Průvodce přípravou, která má systém.',description:'Ukázkový průvodce pro každého, kdo chce pochopit jednotlivé fáze soutěžní přípravy. Trénink, stravovací režim, regenerace a příprava na soutěžní den v jednom přehledném konceptu.',chapters:['Plánování soutěžní sezóny','Struktura tréninku v přípravě','Výživa a sledování progresu','Peak week a soutěžní den']},
{id:'hypertrophy',title:'Hypertrofie bez zbytečností',short:'Hypertrofie bez zbytečností',line1:'BUDUJ',line2:'SVALY.',category:'Trénink',price:690,pages:112,volume:'02',image:D.coaches[2].image,accent:'#b8c3ad',summary:'Méně domněnek. Více kvalitních opakování. Pochop principy svalového růstu.',description:'Ukázkový e-book zaměřený na principy efektivního silového tréninku. Návrh obsahu propojuje volbu cviků, práci s intenzitou a dlouhodobé plánování progresu.',chapters:['Základy svalové hypertrofie','Objem, intenzita a frekvence','Výběr cviků a technika','Logbook a vyhodnocování progresu']},
{id:'nutrition',title:'Výživa pro skutečný progres',short:'Výživa pro progres',line1:'JEZ PRO',line2:'VÝKON.',category:'Výživa',price:590,pages:96,volume:'03',image:D.coaches[4].image,accent:'#b5bbc8',summary:'Výživa, která zapadá do tvého života. Základy, na kterých můžeš stavět.',description:'Ukázkový koncept srozumitelného průvodce výživou pro sportovce. Přibližuje energetický příjem, makroživiny i praktické plánování jídel bez zbytečných extrémů.',chapters:['Energetická bilance v praxi','Bílkoviny, sacharidy a tuky','Výživa kolem tréninku','Udržitelné stravovací návyky']}
];
const SERVICES=[{id:'soutezni-priprava',number:'01',title:'Soutěžní příprava',desc:'Od prvního startu až po velké pódium. Individuální vedení pro závodníky všech úrovní.',intro:'Každý detail rozhoduje. Postav svou přípravu na zkušenostech trenérů, kteří sami znají soutěžní pódium.',items:['Individuální tréninkový plán','Výživa a suplementační protokol','Pravidelné kontroly a komunikace','Příprava naturálních i asistovaných závodníků'],photo:D.coaches[0].image,coaches:[0,1,2,4,6]},
{id:'lifestyle',number:'02',title:'Lifestyle coaching',desc:'Silnější a zdravější verze tebe. Dlouhodobý progres, který zapadá do tvého života.',intro:'Zlepši svou postavu, kondici a dosáhni vlastních cílů. S lidským přístupem a plánem, který respektuje tvůj každodenní život.',items:['Trénink sestavený podle tvých možností','Výživa s ohledem na individuální cíle','Kontrola techniky a sledování výkonu','Otevřená komunikace a dlouhodobá spolupráce'],photo:D.coaches[1].image,coaches:[1,2,3,6]},
{id:'pozing',number:'03',title:'Pózing',desc:'Ukaž práci, kterou máš za sebou. Technika, sebejistota a tvůj vlastní projev.',intro:'Předveď svou nejlepší verzi. Pózing propojuje techniku, estetiku a sebevědomý projev na pódiu.',items:['Kulturistika a Classic Physique s Danielem Bromem','Bikini a wellness fitness s Janou Pavlovičovou','Osobní i online lekce podle trenéra','Individuální přístup ke scénickému projevu'],photo:D.coaches[5].image,coaches:[5,6]},
{id:'junior',number:'04',title:'Junior coaching',desc:'Správné základy od začátku. Zodpovědná cesta mladých sportovců k jejich cílům.',intro:'První kroky mají velký význam. Lukáš Fürle propojuje vlastní závodní zkušenosti s důrazem na individualitu, zdraví a otevřenou komunikaci.',items:['Individuální vedení s Lukášem Fürlem','Budování tréninkových základů','Příprava začínajících závodníků','Důraz na fyzický i psychický progres'],photo:D.coaches[3].image,coaches:[3]}];
let state={cart:[],owned:[],orders:[],loggedIn:false,name:'Alex Novák',email:'alex@example.test'};
try { const saved=JSON.parse(localStorage.getItem('tpc-prototype-v1')); if(saved&&typeof saved==='object') {state={...state,...saved};state.cart=(state.cart||[]).filter(id=>BOOKS.some(b=>b.id===id));state.owned=(state.owned||[]).filter(id=>BOOKS.some(b=>b.id===id));if(!Array.isArray(state.orders))state.orders=[];} }catch{}
function save(){try{localStorage.setItem('tpc-prototype-v1',JSON.stringify(state));}catch{}updateCartCount();}
function updateCartCount(){$('#cart-count').textContent=state.cart.length;}
const owned=id=>state.owned.includes(id);
const findBook=id=>BOOKS.find(b=>b.id===id);
let lastFocus=null,toastTimeout=null,filter='Všechny',search='';
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function modal(html,cls='',label='Detail'){
 lastFocus=document.activeElement;
 $('#overlay').hidden=false;document.body.classList.add('locked');
 $('#modal-root').innerHTML=`<section class="modal ${cls}" role="dialog" aria-modal="true" aria-label="${esc(label)}" tabindex="-1"><button class="modal-close" data-action="close" aria-label="Zavřít">×</button>${html}</section>`;
 $('.modal').focus();
}
function closeModal(){ $('#modal-root').innerHTML='';$('#overlay').hidden=true;document.body.classList.remove('locked');if(lastFocus?.isConnected)lastFocus.focus(); }
function bookCover(b,lock=true){return `<div class="book-stage"><span class="book-badge">TPC EDUCATION / VOL. ${b.volume}</span><div class="book" style="--book-accent:${b.accent}">${img(b.image,'')}<div class="book-top"><span>TEAM PROGRESSIVE</span><span>TPC</span></div><span class="book-volume">${b.volume}</span><div class="book-title">${b.line1}<em>${b.line2}</em></div><div class="book-bottom"><span>THE PROGRESSIVE SERIES</span><span>E-BOOK / ${b.pages} STR.</span></div></div>${lock?`<span class="book-lock">${icon(owned(b.id)?'check':'lock')} ${owned(b.id)?'Ve tvé knihovně':'Odemkni svůj potenciál'}</span>`:''}</div>`;}
function productCard(b){return `<article class="product-card" tabindex="0" role="button" aria-label="Zobrazit ${b.title}" data-action="product" data-id="${b.id}">${bookCover(b)}<div class="product-meta"><span class="product-category">${b.category} · PDF e-book</span><span class="product-price">${currency(b.price)}</span></div><h3>${b.title}</h3><p>${b.summary}</p><div class="product-bottom"><span>${owned(b.id)?'Otevřít v knihovně':'Prohlédnout e-book'}</span><span>↗</span></div></article>`;}
function coachCard(c,i=0){return `<a class="coach-card" href="#coach/${c.slug}"><div class="coach-photo">${img(c.image,c.name)}${i===0?'<span class="coach-tag">HEAD COACH</span>':c.slug==='jana-pavlovicova'?'<span class="coach-tag">IFBB PRO</span>':''}</div><div class="coach-info"><div><h3>${c.name}</h3><p>${c.role}</p></div><span>↗</span></div></a>`;}
const note=(text='Ukázkové e-booky a ceny slouží pouze pro prezentaci návrhu. Nejde o skutečnou nabídku.')=>`<p class="demo-note">${icon('info')}${text}</p>`;
function pageHero(eyebrow,title,text='',back=''){return `<section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="#home">Úvod</a><span>/</span>${back?`<a href="#${back}">${back==='team'?'Náš tým':'Coaching'}</a><span>/</span>`:''}<span>${eyebrow}</span></div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${text?`<p>${text}</p>`:''}</div></section>`;}
function cta(){return `<section class="cta-section"><div class="container cta-inner"><div><div class="eyebrow">TVŮJ DALŠÍ KROK</div><h2>Tvůj progres.<br>Naše společná mise.</h2><p>První krok začíná rozhodnutím. Ten další už uděláme společně.</p></div><a class="button" href="#contact">Začni svou cestu <span>↗</span></a></div></section>`;}
function mediaBlock(){return `<div class="media-grid"><a class="video-tile" href="https://www.youtube.com/watch?v=${D.videos[0]}" target="_blank" rel="noopener">${img(D.team,'Team Progressive Coaches')}<span class="play">▶</span><div class="video-copy"><small>YOUTUBE / TEAM PROGRESSIVE COACHES</small><h3>Blíž k týmu.<br>Blíž k progresu.</h3></div></a><a class="podcast-tile" href="https://open.spotify.com/show/0MRU3uLcMiGhAb53W6SHKZ" target="_blank" rel="noopener"><span class="podcast-bg">1%</span><div class="eyebrow">1 % BB PODCAST</div><div><h3>O kulturistice.<br>Bez filtru.</h3><p>Poslechni si podcast ze světa bodybuildingu. Na cestě, ve fitku i mimo něj.</p></div><span class="text-link">Pustit na Spotify <span>↗</span></span></a></div>`;}
function home(){return `<section class="hero">${img(D.hero,'Daniel Švach při soutěžním pózingu','hero-image',true)}<span class="hero-year">EST. MINDSET / EVERY DAY</span><div class="container hero-content"><div class="eyebrow">TEAM PROGRESSIVE COACHES</div><h1>Mentalita<br><span class="gold">šampionů.</span></h1><p class="hero-description">Za každým výsledkem je příběh. Disciplína. A tým, který tě posouvá dál. Začni psát ten svůj s námi.</p><div class="hero-buttons"><a class="button" href="#team">Poznej náš tým <span>↗</span></a><a class="button button-outline" href="#contact">Začni svou cestu <span>↗</span></a></div></div><span class="hero-side">BUILT ON DISCIPLINE. DRIVEN BY PROGRESS.</span><div class="hero-foot"><div class="container"><a href="#services" class="scroll-note"><span>↓</span> OBJEV SVŮJ POTENCIÁL</a><div class="hero-credit"><small>HEAD COACH & ZAKLADATEL</small><strong>Daniel Švach</strong></div></div></div></section>
<section class="proof-strip"><div class="container proof-grid"><div class="proof-caption">Zkušenosti z pódia.<br>Přístup zaměřený na tebe.</div><div class="proof-stat"><strong>7</strong><span>trenérů.<br>Jeden společný mindset.</span></div><div class="proof-stat"><strong>8 000+</strong><span>osobních lekcí<br>Daniela Švacha.</span></div><div class="proof-stat"><strong>IFBB PRO</strong><span>Jana Pavlovičová<br>Profesionální karta 2025.</span></div></div></section>
<div class="container intro"><div><div class="eyebrow">VÍC NEŽ JEN COACHING</div><h2>Individuální cesta.<br><span class="outline-text">Týmová síla.</span></h2></div><div class="intro-copy"><p>Jsme Team Progressive Coaches. Tým zkušených coachů, které spojuje kulturistika, osobní přístup a chuť posouvat hranice.</p><p>Ať míříš na soutěžní pódium, nebo chceš být silnější v každodenním životě, najdeš u nás trenéra pro svou cestu. S jasným plánem, otevřenou komunikací a respektem k tvým cílům.</p><a class="text-link" href="#about">Poznej filozofii týmu <span>↗</span></a></div></div>
<section class="section services-section" id="services"><div class="container"><div class="section-head"><div><div class="eyebrow">NAŠE SPECIALIZACE</div><h2>Tvůj cíl.<br>Správné vedení.</h2></div><p>Každá cesta je jiná. Najdi způsob spolupráce, který bude dávat smysl právě tobě.</p></div>${SERVICES.map(s=>`<a class="service-row" href="#service/${s.id}"><span class="service-number">${s.number}</span><h3>${s.title}</h3><p>${s.desc}</p><span class="arrow">↗</span></a>`).join('')}</div></section>
<section class="section"><div class="container"><div class="section-head"><div><div class="eyebrow">LIDÉ ZA TVÝM PROGRESEM</div><h2>Zkušenosti, které<br>tě posunou dál.</h2></div><a href="#team" class="text-link">Celý tým / 7 trenérů <span>↗</span></a></div><div class="coach-grid">${[D.coaches[0],D.coaches[1],D.coaches[3],D.coaches[6]].map((c,i)=>coachCard(c,i)).join('')}</div></div></section>
<section class="manifesto">${img(D.team,'Členové Team Progressive Coaches')}<div class="container"><div class="eyebrow">PROGRES SE NEDĚJE NÁHODOU</div><h2>Práce je tvoje.<br><span class="gold">Záda ti kryjeme my.</span></h2><p>Za každým startem stojí měsíce práce. Podívej se na skutečné závodní a klientské úspěchy našeho týmu.</p><a class="text-link" href="#results">Výsledky, které mluví za nás <span>↗</span></a></div></section>
<section class="section books-section"><div class="container"><div class="section-head"><div><div class="eyebrow">TPC EDUCATION / DIGITÁLNÍ KNIHOVNA</div><h2>Znalosti jsou<br>tvá další výhoda.</h2></div><div><p>Trénuj s rozumem. Rozšiř svůj pohled na přípravu, výživu i svalový růst.</p><a href="#shop" class="text-link" style="margin-top:20px">Prozkoumat e-booky <span>↗</span></a></div></div><div class="product-grid">${BOOKS.map(productCard).join('')}</div>${note()}</div></section>
<section class="section"><div class="container"><div class="section-head"><div><div class="eyebrow">ZA HRANICEMI TRÉNINKU</div><h2>Žijeme tím.<br>A mluvíme o tom.</h2></div><a class="text-link" href="#media">YouTube & podcasty <span>↗</span></a></div>${mediaBlock()}</div></section>${cta()}`;}
function team(){return `${pageHero('Náš tým','Sedm osobností.<br><span class="gold">Jeden mindset.</span>','Zkušenosti z vlastních příprav, osobních tréninků a práce s klienty. Vyber si člověka, se kterým si sedneš i mimo tréninkový plán.')}<section class="section"><div class="container coach-grid all">${D.coaches.map(coachCard).join('')}</div></section>${cta()}`;}
function renderCoachContent(content){
 const groups=[];let paragraph='';const flush=()=>{if(paragraph){groups.push('<p>'+esc(paragraph)+'</p>');paragraph='';}};
 const heading=/(úspěchy|certifikace|^IFBB$|^NPC$|^PŘÍPRAVA$|^O pozingu$|^služby$|^Stage make-up$|REVOLUCE V|^Trénink$|^POZING$|^NUTRIČNÍ$|^SUPLEMENTACE$|KONTROLY|^20\d\d$)/i;
 for(const text of content){if(heading.test(text)){flush();groups.push('<h3>'+esc(text)+'</h3>');}else{if(/^\d+[.)]?\s|^\d{1,2}\.\d/.test(text))flush();paragraph+=(paragraph?' ':'')+text;}}flush();return groups.join('');
}
function coach(slug){const c=D.coaches.find(c=>c.slug===slug);if(!c)return notFound();return `<section class="section"><div class="container"><div class="breadcrumbs"><a href="#home">Úvod</a><span>/</span><a href="#team">Náš tým</a><span>/</span>${c.name}</div><div class="coach-detail"><div class="coach-detail-photo">${img(c.image,c.name,'',true)}<a class="button" href="#contact/${c.slug}">Chci spolupracovat <span>↗</span></a></div><div><div class="eyebrow">${c.role}</div><h1>${c.name.split(' ')[0]}<br><span class="gold">${c.name.split(' ').slice(1).join(' ')}</span></h1><div class="coach-copy">${renderCoachContent(c.content)}</div><div class="source-note">Biografie a výsledky převzaty z původního webu. Časové údaje odpovídají původnímu textu.</div></div></div></div></section>${c.gallery.length?`<section class="section services-section"><div class="container"><div class="section-head"><div><div class="eyebrow">Z TRÉNINKU I PÓDIA</div><h2>Galerie</h2></div></div><div class="gallery-grid">${c.gallery.slice(0,12).map(u=>galleryTile(u,c.name)).join('')}</div></div></section>`:''}${cta()}`;}
function services(){return `${pageHero('Coaching','Každý cíl si zaslouží<br><span class="gold">vlastní plán.</span>','Soutěžní ambice i každodenní progres. Najdi formu spolupráce, která je pro tebe.')}<section class="section services-section"><div class="container">${SERVICES.map(s=>`<a class="service-row" href="#service/${s.id}"><span class="service-number">${s.number}</span><h3>${s.title}</h3><p>${s.desc}</p><span class="arrow">↗</span></a>`).join('')}</div></section>${cta()}`;}
function service(id){const s=SERVICES.find(s=>s.id===id);if(!s)return notFound();return `<section class="section"><div class="container"><div class="breadcrumbs"><a href="#home">Úvod</a><span>/</span><a href="#services">Coaching</a><span>/</span>${s.title}</div><div class="service-detail"><div><div class="eyebrow">COACHING / ${s.number}</div><h1>${s.title}</h1><p>${s.intro}</p><ul class="checklist">${s.items.map(i=>`<li>${i}</li>`).join('')}</ul><a href="#contact" class="button">Probrat spolupráci <span>↗</span></a></div>${img(s.photo,s.title,'',true)}</div></div></section><section class="section services-section"><div class="container"><div class="section-head"><div><div class="eyebrow">TVÍ PRŮVODCI</div><h2>Najdi svého coache.</h2></div></div><div class="coach-grid">${s.coaches.map(i=>coachCard(D.coaches[i],i)).join('')}</div></div></section>${cta()}`;}
function about(){return `${pageHero('O nás','Progres je směr.<br><span class="gold">Tým je síla.</span>','Team Progressive Coaches propojuje individuální přístup s vlastními zkušenostmi trenérů ze světa fitness a kulturistiky.')}<section class="section"><div class="container service-detail"><div><div class="eyebrow">TEAM PROGRESSIVE COACHES</div><h2>Lidé, kteří žijí<br>tím, co učí.</h2><p>Tým založil hlavní trenér Daniel Švach. Vedle soutěžní přípravy se naši coachové věnují lifestyle klientům, osobnímu tréninku, pózingu a mladým závodníkům.</p><p>Každý trenér přináší svůj vlastní příběh, specializaci a přístup. Spojuje nás důraz na individualitu a otevřenou komunikaci.</p><a class="button" href="#team">Poznej náš tým <span>↗</span></a></div>${img(D.team,'Team Progressive Coaches')}</div></section>${cta()}`;}
function results(){const highlights=[['1. místo','EVLS 2024','Classic physique class A','Klientský úspěch Daniela Švacha'],['1. místo + absolutně','Mistrovství Evropy 2023','Zaznamenáno mezi klientskými úspěchy','Klientský úspěch Davida Procházky'],['IFBB PRO','Champions Classic 2025','Bikiny fitness Overall Winner','Jana Pavlovičová']];return `${pageHero('Výsledky & úspěchy','Práce, která je<br><span class="gold">vidět.</span>','Skutečné výsledky a soutěžní zkušenosti převzaté z profilů našeho týmu. Za každým umístěním je vlastní cesta.')}<section class="section"><div class="container"><div class="result-grid">${highlights.map(x=>`<article class="result-card"><strong>${x[0]}</strong><h3>${x[1]}</h3><p>${x[2]}</p><small>${x[3]}</small></article>`).join('')}</div><div class="section-head" style="margin-top:70px"><div><div class="eyebrow">Z PÓDIA A ZÁKULISÍ</div><h2>Momenty progresu.</h2></div><a class="text-link" href="#gallery">Celá galerie <span>↗</span></a></div><div class="gallery-grid">${D.gallery.slice(0,12).map(u=>galleryTile(u)).join('')}</div><div class="notice" style="margin-top:30px">${icon('info')}Úplné závodní a klientské úspěchy najdeš na profilech jednotlivých trenérů. Nevytváříme smyšlené klientské reference.</div></div></section>${cta()}`;}
function galleryTile(u,name='Fotografie z původní galerie TPC'){return `<button data-action="image" data-src="${esc(u)}" aria-label="Zvětšit fotografii: ${esc(name)}">${img(u,name)}</button>`;}
function gallery(){return `${pageHero('Galerie','Moment za momentem.<br><span class="gold">Progres v obrazech.</span>','Autentické fotografie z původních galerií týmu. Soutěže, tréninky a společné momenty.')}<section class="section"><div class="container gallery-grid">${D.gallery.map(u=>galleryTile(u)).join('')}</div></section>${cta()}`;}
function media(){return `${pageHero('YouTube & podcasty','Kulturistika<br><span class="gold">i mimo pódium.</span>','Původní videa a podcast týmu. Nahlédni do světa TPC i mezi tréninky.')}<section class="section"><div class="container">${mediaBlock()}<div class="section-head" style="margin-top:65px"><div><div class="eyebrow">Z PŮVODNÍHO WEBU</div><h2>Další videa.</h2></div></div><div class="product-grid">${D.videos.slice(1).map((id,i)=>`<a class="video-tile" href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener">${img(D.coaches[i+1].image,'Ilustrační fotografie trenéra z týmu')}<span class="play">▶</span><div class="video-copy"><small>YOUTUBE / VIDEO ${i+2}</small><h3>Ze světa<br>Team Progressive</h3></div></a>`).join('')}</div><p class="source-note">Odkazy na videa pocházejí z původního webu. Fotografie slouží jako ilustrační náhledy návrhu.</p></div></section>${cta()}`;}
function shop(){filter='Všechny';search='';return `${pageHero('TPC Education','Další úroveň<br><span class="gold">začíná v hlavě.</span>','Digitální průvodci pro tvůj trénink, přípravu a výživu. Všechny znalosti na jednom místě, vždy po ruce.')}<section class="section shop-dark"><div class="container"><div class="shop-toolbar"><div class="filter-tabs">${['Všechny','Soutěžní příprava','Trénink','Výživa'].map((t,i)=>`<button class="filter-tab ${!i?'active':''}" data-action="filter" data-category="${t}">${t}</button>`).join('')}</div><input class="search-input" type="search" id="book-search" placeholder="Hledat e-book…" aria-label="Hledat e-book"></div><div class="product-grid" id="shop-products">${BOOKS.map(productCard).join('')}</div>${note('Ukázkový katalog. E-booky, jejich obsahy a ceny jsou smyšlené. Nákupem si lze vyzkoušet pouze simulaci odemčení.')}</div></section><section class="section services-section"><div class="container"><div class="section-head"><div><div class="eyebrow">JEDNODUŠE. NA JEDNOM MÍSTĚ.</div><h2>Od inspirace<br>k vlastní knihovně.</h2></div></div><div class="result-grid"><article class="result-card"><strong>01</strong><h3>Vyber si téma.</h3><p>Prohlédni si obsah, zaměření a ukázku každého e-booku.</p></article><article class="result-card"><strong>02</strong><h3>Projdi objednávkou.</h3><p>V tomto návrhu tě čeká jen názorná simulace. Žádné platební údaje.</p></article><article class="result-card"><strong>03</strong><h3>Otevři knihovnu.</h3><p>Po simulovaném potvrzení najdeš e-book odemčený ve své členské zóně.</p></article></div></div></section>`;}
function updateShop(){const books=BOOKS.filter(b=>(filter==='Všechny'||b.category===filter)&&(b.title+' '+b.summary).toLocaleLowerCase('cs').includes(search.toLocaleLowerCase('cs')));$('#shop-products').innerHTML=books.length?books.map(productCard).join(''):'<div class="empty"><h3>Tady je zatím prázdno.</h3><p>Zkus jiné téma nebo vyhledávání.</p><button class="button button-outline" data-action="clear-filter">Zobrazit vše ↗</button></div>';}
function dashboardShell(active,content,admin=false){const links=admin?[['admin','grid','Přehled'],['admin/products','book','E-booky'],['admin/customers','user','Zákazníci'],['admin/orders','order','Objednávky'],['admin/content','grid','Obsah webu']]:[['account','grid','Přehled'],['library','book','Moje e-booky'],['orders','order','Moje objednávky'],['profile','user','Osobní údaje'],['security','lock','Zabezpečení']];return `<div class="dashboard"><aside class="dashboard-side"><div class="dashboard-user"><div class="avatar">${admin?'TP':esc(state.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}</div><strong>${admin?'TPC Administration':esc(state.name)}</strong><small>${admin?'Ukázkový administrátor':'Demo členský účet'}</small></div>${links.map(([url,ic,label])=>`<a href="#${url}" class="${url===active?'active':''}">${icon(ic)}${label}</a>`).join('')}${admin?'<a href="#account">← Členská zóna</a>':`<button data-action="logout">${icon('logout')}Odhlásit se</button>`}</aside><div class="dashboard-main">${content}</div></div>`;}
function dashHeading(title,desc,tag='DEMO ÚČET'){return `<div class="dashboard-heading"><div><h1>${title}</h1><p>${desc}</p></div><span class="pill">${tag}</span></div>`;}
function libraryCard(b){const access=owned(b.id);return `<article class="library-card ${access?'':'locked-book'}">${bookCover(b,false)}<div class="access-label">${icon(access?'check':'lock')}${access?'ODEMČENO · TVŮJ E-BOOK':'ZAMČENO · ZPŘÍSTUPNÍ SE PO PLATBĚ'}</div><h3>${b.title}</h3><p>${b.pages} stran · PDF · ${b.category}</p><button class="button ${access?'':'button-outline'}" data-action="${access?'read':'product'}" data-id="${b.id}">${access?'Otevřít e-book':'Odemknout za '+currency(b.price)} <span>${access?'↗':'+'}</span></button></article>`;}
function library(){return dashboardShell('library',`${dashHeading('Moje e-booky','Tvoje znalosti. Tvoje tempo. Všechno na jednom místě.')}<div class="notice">${icon('info')}Toto je ukázka členské knihovny. Zamčený e-book odemkneš simulací nákupu. Neproběhne skutečná platba.</div><div class="library-grid">${BOOKS.map(libraryCard).join('')}</div>`);}
function account(){if(!state.loggedIn)return login();return dashboardShell('account',`${dashHeading('Vítej zpět, '+esc(state.name.split(' ')[0])+'.','Každý den je další příležitost posunout se dál.')}<div class="stats"><div class="stat"><small>Moje e-booky</small><strong>${state.owned.length.toString().padStart(2,'0')}</strong><span>V TVÉ DIGITÁLNÍ KNIHOVNĚ</span></div><div class="stat"><small>Moje objednávky</small><strong>${state.orders.length.toString().padStart(2,'0')}</strong><span>UKÁZKOVÉ OBJEDNÁVKY</span></div><div class="stat"><small>Členství</small><strong>PROGRESS</strong><span>TVÁ CESTA ZAČÍNÁ TADY</span></div></div><div class="section-head"><div><div class="eyebrow">TVÁ DIGITÁLNÍ ZÓNA</div><h2 style="font-size:38px">Pokračuj v progresu.</h2></div><a class="text-link" href="#library">Celá knihovna <span>↗</span></a></div><div class="library-grid">${BOOKS.map(libraryCard).join('')}</div>`);}
function login(){return `<div class="container account-welcome"><div><div class="eyebrow">TVÁ ČLENSKÁ ZÓNA</div><h1>Vše pro tvůj<br><span class="gold">další progres.</span></h1><p>Vlastní knihovna e-booků, přehled objednávek a tvůj účet. Vstup do ukázkové členské zóny a prohlédni si, jak může fungovat.</p><div class="notice">${icon('info')}Jde o prezentační prototyp. Žádný skutečný účet se nevytváří a heslo není potřeba.</div></div><div class="form-card"><div class="eyebrow">VÍTEJ V TÝMU</div><h3>Tvoje místo pro progres.</h3><p>Prohlédni si dashboard a vyzkoušej si nákup i odemčení e-booku.</p><label class="field">Ukázkové jméno<input id="demo-name" type="text" value="${esc(state.name)}" maxlength="80" autocomplete="off"></label><button class="button" data-action="login">Vstoupit do demo účtu <span>↗</span></button><button class="form-secondary" data-action="register">Prohlédnout návrh registrace</button><button class="form-secondary" data-action="reset-password">Jak bude fungovat obnova hesla?</button><p class="small-disclaimer">Použij smyšlené jméno. Data ukázky zůstávají v tomto prohlížeči.</p></div></div>`;}
function orderTable(orders){return orders.length?`<div class="table-scroll"><table><thead><tr><th>OBJEDNÁVKA</th><th>DATUM</th><th>E-BOOKY</th><th>CELKEM</th><th>STAV</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr><td>#${esc(o.id)}</td><td>${esc(o.date)}</td><td>${o.items.length} ${o.items.length===1?'e-book':'e-booky'}</td><td>${currency(o.total)}</td><td><span class="status">Demo potvrzeno</span></td><td><button data-action="order-detail" data-id="${esc(o.id)}">Detail ↗</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>Tvoje cesta teprve začíná.</h3><p>Zatím tu nemáš žádné ukázkové objednávky.</p><a class="button" href="#shop">Prohlédnout e-booky ↗</a></div>';}
function orders(){return dashboardShell('orders',dashHeading('Moje objednávky','Přehled tvých ukázkových nákupů.')+orderTable(state.orders));}
function profile(){return dashboardShell('profile',`${dashHeading('Osobní údaje','Všechno důležité pro tvůj účet.')}<div class="panel" style="max-width:620px"><form id="profile-form"><label class="field">Jméno a příjmení<input name="name" value="${esc(state.name)}" required maxlength="80"></label><label class="field">Ukázkový e-mail<input name="email" type="email" value="${esc(state.email)}" required maxlength="150"></label><button class="button">Uložit změny <span>↗</span></button><p class="small-disclaimer">Používej pouze smyšlené údaje. Ukládají se lokálně do prohlížeče.</p></form></div>`);}
function security(){return dashboardShell('security',`${dashHeading('Zabezpečení účtu','Návrh nastavení zákaznického účtu.')}<div class="panel"><h3>Heslo & přihlášení</h3><p>V ostré verzi zde bude změna hesla, ověření e-mailu a bezpečné přihlášení. Tento prezentační účet žádné heslo nepoužívá.</p><button class="button button-outline" data-action="reset-password">Ukázka obnovy hesla ↗</button></div><div class="panel"><h3>Data ukázky</h3><p>Vymažeš lokální ukázkové objednávky, odemčené e-booky i profil a vrátíš prototyp do výchozího stavu.</p><button class="button button-outline" data-action="reset-demo">Resetovat demo ↺</button></div>`);}
function contact(coachSlug=''){return `${pageHero('Spolupráce','První krok je<br><span class="gold">na tobě.</span>','Řekni nám, kam míříš. Společně můžeme najít cestu.')}<section class="section"><div class="container contact-grid"><div><div class="eyebrow">ZAČNI SVOU CESTU</div><h2>Tvůj příběh.<br>Náš další<br>společný progres.</h2><p>Vyber si trenéra nebo si nech s výběrem poradit. Každý dobrý plán začíná tím, že se poznáme.</p><div class="contact-details"><small>TEAM PROGRESSIVE COACHES</small><a href="https://instagram.com/teamprogressivecoaches/" target="_blank" rel="noopener">Instagram / @teamprogressivecoaches ↗</a><a href="#team">Poznat všechny trenéry ↗</a></div><div class="notice" style="margin-top:35px">${icon('info')}Formulář je pouze ukázka. Nic se neodesílá. Pro skutečný kontakt použij profil týmu na Instagramu.</div></div><form class="form-card" id="contact-form"><h3>Pojďme se poznat.</h3><p>Ukázka poptávky spolupráce</p><div class="form-row"><label class="field">Tvoje jméno<input name="name" placeholder="Ukázkové jméno" required maxlength="80"></label><label class="field">E-mail<input name="email" type="email" placeholder="alex@example.test" required maxlength="150"></label></div><label class="field">S kým chceš spolupracovat?<select name="coach"><option>Nechám si poradit</option>${D.coaches.map(c=>`<option ${c.slug===coachSlug?'selected':''}>${c.name}</option>`).join('')}</select></label><label class="field">Tvůj cíl<select name="goal"><option>Soutěžní příprava</option><option>Nabrání svalové hmoty</option><option>Redukce tuku</option><option>Zlepšení kondice</option><option>Pózing</option><option>Junior coaching</option></select></label><label class="field">Něco málo o tvém cíli<textarea name="message" placeholder="Co bys chtěl/a změnit?" maxlength="1000"></textarea></label><label class="check"><input type="checkbox" required><span>Rozumím, že jde o ukázkový formulář, a používám pouze smyšlené údaje.</span></label><button class="button">Vyzkoušet odeslání <span>↗</span></button></form></div></section>`;}
const sampleOrders=[{id:'TPC-2026-024',date:'30. 10. 2026',items:['prep'],total:890},{id:'TPC-2026-023',date:'29. 10. 2026',items:['hypertrophy','nutrition'],total:1280},{id:'TPC-2026-022',date:'28. 10. 2026',items:['nutrition'],total:590}];
function admin(section=''){let body='';const active='admin'+(section?'/'+section:'');const adminNote=`<div class="notice">${icon('info')}Ukázková administrace. Všechny statistiky, zákazníci a objednávky níže jsou smyšlené. Správu si lze prohlédnout bez přihlášení.</div>`;
if(!section){body=`${dashHeading('Přehled podnikání','Všechno důležité na jednom místě.','DEMO ADMINISTRACE')}${adminNote}<div class="stats"><div class="stat"><small>Ukázkové tržby / říjen</small><strong>24 860 Kč</strong><span>SMYŠLENÁ DEMO DATA</span></div><div class="stat"><small>Ukázkové objednávky</small><strong>32</strong><span>ZA VYBRANÉ OBDOBÍ</span></div><div class="stat"><small>Ukázkoví zákazníci</small><strong>128</strong><span>CELKEM V DEMO DATABÁZI</span></div></div><div class="admin-columns"><div class="panel"><h3>Vývoj ukázkových tržeb</h3><div class="chart">${[32,47,39,68,55,80,95].map((v,i)=>`<div class="chart-col"><div class="chart-bar" style="height:${v}%"></div><small>${['KVĚ','ČER','ČVC','SRP','ZÁŘ','ŘÍJ','LIS'][i]}</small></div>`).join('')}</div><p class="small-disclaimer">Ilustrační graf. Nesleduje skutečné prodeje.</p></div><div class="panel"><h3>Nejprodávanější e-booky</h3>${BOOKS.map((b,i)=>`<div class="admin-list"><span>${b.short}<br><small>UKÁZKOVÝ PRODUKT</small></span><strong>${[16,10,6][i]}×</strong></div>`).join('')}</div></div><div class="panel"><h3>Poslední objednávky</h3>${orderTable([...state.orders,...sampleOrders].slice(0,5))}</div>`;}
else if(section==='products'){body=`${dashHeading('Správa e-booků','Publikace, ceny a digitální obsah.','DEMO ADMINISTRACE')}${adminNote}<button class="button" data-action="admin-product" style="margin-bottom:30px">+ Přidat ukázkový e-book</button><div class="table-scroll"><table><thead><tr><th>E-BOOK</th><th>KATEGORIE</th><th>CENA</th><th>STAV</th><th></th></tr></thead><tbody>${BOOKS.map(b=>`<tr><td>${b.title}</td><td>${b.category}</td><td>${currency(b.price)}</td><td><span class="status">Ukázkově publikováno</span></td><td><button data-action="admin-product" data-id="${b.id}">Upravit ↗</button></td></tr>`).join('')}</tbody></table></div>`;}
else if(section==='customers'){body=`${dashHeading('Zákazníci','Přehled účtů a přístupů k e-bookům.','DEMO ADMINISTRACE')}${adminNote}<div class="panel"><h3>Ukázkové zákaznické účty</h3><div class="table-scroll"><table><thead><tr><th>ZÁKAZNÍK</th><th>E-MAIL</th><th>OBJEDNÁVKY</th><th>STAV</th><th></th></tr></thead><tbody>${[['Alex Novák','alex@example.test',3],['Petra Ukázková','petra@example.test',1],['Jan Demo','jan@example.test',2]].map(c=>`<tr><td>${c[0]}</td><td>${c[1]}</td><td>${c[2]}</td><td><span class="status">Aktivní</span></td><td><button data-action="admin-customer" data-name="${c[0]}">Detail ↗</button></td></tr>`).join('')}</tbody></table></div></div>`;}
else if(section==='orders'){body=`${dashHeading('Objednávky','Názorný přehled digitálních nákupů.','DEMO ADMINISTRACE')}${adminNote}${orderTable([...state.orders,...sampleOrders])}`;}
else if(section==='content'){body=`${dashHeading('Obsah webu','Přehledná správa bez programování.','DEMO ADMINISTRACE')}${adminNote}<div class="panel"><h3>Stránky & obsah</h3>${[['Úvodní stránka','Hero sekce, služby a CTA'],['Trenérské profily','7 profilů, biografie a úspěchy'],['Galerie',D.gallery.length+' původních fotografií'],['YouTube & podcasty','4 videa a 1 podcast']].map(x=>`<div class="admin-list"><span>${x[0]}<br><small>${x[1]}</small></span><button data-action="admin-content" data-name="${x[0]}">Upravit ↗</button></div>`).join('')}</div>`;}
else{return notFound();}return dashboardShell(active,body,true);}
function notFound(){return pageHero('Stránka nenalezena','Tudy cesta<br><span class="gold">nevede.</span>')+'<div class="container section"><a class="button" href="#home">Zpět na úvod ↗</a></div>';}
function route(){closeModal();$('#mobile-nav').hidden=true;$('.menu-button').setAttribute('aria-expanded','false');const [page='home',id='']=(location.hash.slice(1)||'home').split('/');const renderer={home,team,coach,services,service,about,results,gallery,media,shop,library,account,orders,profile,security,contact,admin};$('#main').innerHTML=(renderer[page]||notFound)(id);$$('.desktop-nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));const titles={home:'Mentalita šampionů',team:'Náš tým',shop:'E-booky',library:'Moje knihovna',account:'Můj účet',admin:'Ukázka administrace',contact:'Spolupráce',results:'Výsledky',media:'YouTube & podcasty',gallery:'Galerie'};document.title=(titles[page]||'Team Progressive')+' — Team Progressive Coaches';window.scrollTo({top:0,behavior:'instant'});$('#main').classList.remove('reveal');void $('#main').offsetWidth;$('#main').classList.add('reveal');updateCartCount();}
function product(id){const b=findBook(id);if(!b)return;modal(`<div class="product-detail"><div>${bookCover(b)}<p class="small-disclaimer">Ukázková obálka / koncept TPC Education</p></div><div><div class="eyebrow">${b.category} / VOL. ${b.volume}</div><h2>${b.title}</h2><p>${b.description}</p><div class="detail-specs"><span>PDF E-BOOK</span><span>${b.pages} STRAN</span><span>ČESKY</span></div><div class="price">${currency(b.price)}<small>Ukázková cena</small></div><button class="button" data-action="${owned(id)?'read':'add-cart'}" data-id="${id}">${owned(id)?'Otevřít můj e-book':state.cart.includes(id)?'Přejít do košíku':'Přidat do košíku'} <span>↗</span></button><p class="small-disclaimer">${icon('lock')} ${owned(id)?'Odemčeno v rámci této ukázky.':'Po simulované platbě se zpřístupní v tvé knihovně.'} Žádná skutečná platba.</p><ul class="checklist">${b.chapters.map(c=>`<li>${c}</li>`).join('')}</ul></div></div>`,'','Detail ukázkového e-booku');}
function addCart(id){if(!findBook(id))return;if(owned(id)){readBook(id);return;}if(!state.cart.includes(id)){state.cart.push(id);save();toast('E-book je v košíku.');}cart();}
function cart(){const books=state.cart.map(findBook).filter(Boolean);modal(`<div class="eyebrow">TVŮJ DALŠÍ PROGRES</div><h2>Košík <span class="gold">/ ${books.length.toString().padStart(2,'0')}</span></h2><div class="cart-items">${books.length?books.map(b=>`<div class="cart-item"><div class="mini-cover">${img(b.image,'')}<span>${b.line1}<br>${b.line2}</span></div><div><h3>${b.short}</h3><p>${currency(b.price)} <span class="muted">/ PDF e-book</span></p></div><button data-action="remove-cart" data-id="${b.id}" aria-label="Odebrat ${b.title}">×</button></div>`).join(''):'<div class="empty"><h3>Prostor pro nové znalosti.</h3><p>Vyber si první e-book pro svou knihovnu.</p><button class="button" data-action="go-shop">Prohlédnout e-booky ↗</button></div>'}</div>${books.length?`<div class="cart-total"><span>Celkem</span><strong>${currency(books.reduce((sum,b)=>sum+b.price,0))}</strong></div><button class="button" data-action="checkout">Pokračovat k ukázce objednávky <span>↗</span></button>`:''}<p class="small-disclaimer">Interaktivní prototyp. Neproběhne skutečná objednávka ani platba.</p>`,'drawer','Ukázkový košík');}
function checkout(){const books=state.cart.map(findBook).filter(Boolean);if(!books.length){cart();return;}modal(`<div class="eyebrow">UKÁZKA OBJEDNÁVKY / 02</div><h2>O krok blíž<br><span class="gold">k progresu.</span></h2><div class="checkout-layout"><div><div class="notice">${icon('info')}Bez peněz a bez platebních údajů. Tohle je pouze simulace průchodu objednávkou.</div><form id="checkout-form"><label class="field">Ukázkové jméno<input name="name" value="${esc(state.name)}" maxlength="80" required></label><label class="field">Ukázkový e-mail<input name="email" type="email" value="${esc(state.email)}" maxlength="150" required></label><label class="check"><input type="checkbox" required><span>Rozumím, že jde o simulaci. Žádná částka se neúčtuje a používám pouze smyšlené údaje.</span></label><button class="button" style="width:100%">Simulovat úspěšnou platbu <span>↗</span></button><button type="button" data-action="payment-failed" class="form-secondary" style="margin-top:17px;font-size:9px;color:var(--muted)">Vyzkoušet neúspěšnou platbu</button></form></div><aside class="checkout-summary"><h3>Tvoje objednávka</h3>${books.map(b=>`<div class="summary-line"><span>${b.short}</span><strong>${currency(b.price)}</strong></div>`).join('')}<div class="summary-line total"><span>Celkem v ukázce</span><strong>${currency(books.reduce((s,b)=>s+b.price,0))}</strong></div><p class="small-disclaimer">Žádná skutečná platba.<br>E-booky se odemknou jen v tomto prohlížeči.</p></aside></div>`,'','Simulace objednávky');}
function completeOrder(form){const data=new FormData(form);const books=state.cart.map(findBook).filter(Boolean);if(!books.length)return;state.name=String(data.get('name')).trim()||'Alex Novák';state.email=String(data.get('email'));state.loggedIn=true;const order={id:'DEMO-'+Date.now().toString(36).toUpperCase(),date:new Date().toLocaleDateString('cs-CZ'),items:books.map(b=>b.id),total:books.reduce((s,b)=>s+b.price,0)};state.orders.unshift(order);state.owned=[...new Set([...state.owned,...order.items])];state.cart=[];save();modal(`<div class="success-icon">✓</div><div class="eyebrow" style="justify-content:center">SIMULACE DOKONČENA</div><h2>Tvůj progres<br><span class="gold">je odemčený.</span></h2><p>${books.length===1?'E-book je připravený':'E-booky jsou připravené'} ve tvé knihovně. Přesně takto může v budoucnu vypadat přístup po potvrzení platby.</p><button class="button" data-action="go-library">Otevřít moji knihovnu <span>↗</span></button><small>Žádná platba neproběhla. Toto je pouze ukázka.</small>`,'success-modal','Ukázkový nákup dokončen');}
function readBook(id){const b=findBook(id);if(!b)return;if(!owned(id)){product(id);return;}modal(`<div class="reader-toolbar"><span>${b.title} / Náhled</span><button data-action="download-sample" data-id="${b.id}">Stáhnout ukázku ↓</button><button data-action="close" aria-label="Zavřít čtečku">×</button></div><article class="reader-page"><small>TPC EDUCATION / UKÁZKOVÝ E-BOOK ${b.volume}</small><h2>${b.line1}<br><span style="color:#927447">${b.line2}</span></h2><p>TEAM PROGRESSIVE COACHES</p><hr><p><strong>Vítej ve své digitální knihovně.</strong></p><p>Tato stránka ukazuje, jak může vypadat čtení zakoupeného e-booku přímo v členské zóně. Jde o smyšlený produkt připravený pouze pro prezentaci návrhu.</p><p>${b.description}</p><h3 style="font-size:28px;margin:30px 0 18px">Navržený obsah</h3>${b.chapters.map((c,i)=>`<p style="margin-bottom:9px">0${i+1} / ${c}</p>`).join('')}<hr><p style="font-size:9px">PREZENTAČNÍ KONCEPT / Nejde o plnohodnotný e-book ani odborný výživový či tréninkový návod.</p></article>`,'reader','Ukázková čtečka e-booku');}
function downloadSample(id){const b=findBook(id);if(!b||!owned(id))return;const a=document.createElement('a');a.href=`assets/ukazka-${id}.pdf`;a.download=`TPC-ukazka-${id}.pdf`;a.click();toast('Stahuje se krátká ukázka návrhu PDF.');}
function demoInfo(){modal(`<div class="eyebrow">KLIENTSKÝ NÁVRH / V1.0</div><h2>Prohlédni si<br><span class="gold">budoucí progres.</span></h2><p style="margin-top:25px">Interaktivní vizualizace nového webu Team Progressive Coaches. Fotografie, trenéři a jejich výsledky pocházejí z původního webu. E-booky, ceny a data administrace jsou smyšlené ukázky.</p><ul class="checklist"><li>Prohlédni si tým, služby, výsledky a galerii.</li><li>Vyber e-book a projdi ukázkovou objednávkou.</li><li>Simuluj úspěšnou platbu a otevři odemčený e-book.</li><li>Prozkoumej členský účet i ukázkovou administraci.</li></ul><p>Nepoužíváme skutečná hesla, platební údaje ani bankovní integraci. Ukázkový stav se ukládá pouze v tomto prohlížeči.</p><div class="inline-actions"><button class="button" data-action="go-shop">Vyzkoušet e-booky ↗</button><button class="button button-outline" data-action="close">Pokračovat v prohlížení</button></div>`,'','O interaktivním návrhu');}
function adminProduct(id){const b=findBook(id)||BOOKS[0];modal(`<div class="eyebrow">UKÁZKA SPRÁVY PRODUKTU</div><h2>${id?'Upravit':'Nový'} e-book.</h2><form id="admin-product-form" style="margin-top:25px"><label class="field">Název<input name="title" value="${id?b.title:''}" placeholder="Název ukázkového e-booku" required maxlength="100"></label><div class="form-row"><label class="field">Kategorie<select><option>Trénink</option><option>Výživa</option><option>Soutěžní příprava</option></select></label><label class="field">Cena v Kč<input type="number" min="0" max="99999" value="${b.price}"></label></div><label class="field">Popis<textarea>${id?b.description:''}</textarea></label><div class="notice">${icon('info')}Ve skutečné administraci zde bude nahrání obálky a zabezpečeného PDF. Tato ukázka žádné soubory neodesílá.</div><button class="button">Vyzkoušet uložení <span>↗</span></button></form>`,'','Ukázka editoru produktu');}
function adminCustomer(name){modal(`<div class="eyebrow">UKÁZKOVÝ ZÁKAZNÍK</div><h2>${esc(name)}</h2><p style="margin-top:25px">Náhled správy přístupů k digitálním produktům. Změny v této ukázce ovlivní pouze tvoji lokální demo knihovnu.</p>${BOOKS.map(b=>`<div class="admin-list"><span>${b.title}</span><button data-action="toggle-access" data-id="${b.id}" data-name="${esc(name)}">${owned(b.id)?'Odebrat přístup −':'Přidělit přístup +'}</button></div>`).join('')}<p class="small-disclaimer">V ostré verzi bude vyžadována role správce a zásah se zaznamená do auditního logu.</p>`,'','Ukázkový detail zákazníka');}
function register(){modal(`<div class="eyebrow">UKÁZKA REGISTRACE</div><h2>Staň se součástí<br><span class="gold">progresu.</span></h2><form id="register-form" style="margin-top:25px"><div class="form-row"><label class="field">Jméno<input name="first" placeholder="Alex" required maxlength="40"></label><label class="field">Příjmení<input name="last" placeholder="Novák" required maxlength="40"></label></div><label class="field">Ukázkový e-mail<input type="email" name="email" placeholder="alex@example.test" required maxlength="150"></label><div class="notice">${icon('info')}V ostré verzi bude následovat nastavení hesla a ověření e-mailu. Pro vizualizaci heslo nezadávej.</div><label class="check"><input type="checkbox" required><span>Rozumím, že jde o demo účet a údaje zůstávají v tomto prohlížeči.</span></label><button class="button">Vytvořit demo účet <span>↗</span></button></form>`,'','Návrh registrace');}
const handlers={
'close':closeModal,'demo-info':demoInfo,'cart':cart,'product':el=>product(el.dataset.id),'add-cart':el=>addCart(el.dataset.id),'checkout':checkout,
'remove-cart':el=>{state.cart=state.cart.filter(id=>id!==el.dataset.id);save();cart();},
'go-shop':()=>{closeModal();if(location.hash==='#shop')route();else location.hash='shop';},
'go-library':()=>{closeModal();if(location.hash==='#library')route();else location.hash='library';},
'read':el=>readBook(el.dataset.id),'download-sample':el=>downloadSample(el.dataset.id),
'menu':()=>{const nav=$('#mobile-nav');nav.hidden=!nav.hidden;$('.menu-button').setAttribute('aria-expanded',String(!nav.hidden));},
'filter':el=>{filter=el.dataset.category;$$('.filter-tab').forEach(b=>b.classList.toggle('active',b===el));updateShop();},
'clear-filter':()=>{filter='Všechny';search='';$('#book-search').value='';$$('.filter-tab').forEach(b=>b.classList.toggle('active',b.dataset.category===filter));updateShop();},
'login':()=>{state.name=$('#demo-name').value.trim().slice(0,80)||'Alex Novák';state.loggedIn=true;save();route();toast('Vítej v ukázkové členské zóně.');},
'logout':()=>{state.loggedIn=false;save();location.hash='account';route();toast('Demo účet je odhlášený.');},
'register':register,
'reset-password':()=>modal(`<div class="eyebrow">NÁVRH OBNOVY HESLA</div><h2>Zpátky do hry.</h2><p style="margin-top:25px">V ostrém webu zákazník zadá e-mail a obdrží bezpečný odkaz pro nastavení nového hesla. V tomto prototypu se e-maily neposílají a účty nemají hesla.</p><button class="button" data-action="close">Rozumím ↗</button>`,'','Obnova hesla v návrhu'),
'payment-failed':()=>modal(`<div class="success-icon">×</div><h2>Platba se<br>nepodařila.</h2><p style="margin-top:25px">Ukázka neúspěšné platby. E-booky zůstávají zamčené a tvůj košík je připravený na další pokus.</p><button class="button" data-action="checkout">Zkusit simulaci znovu ↗</button><small>Žádná skutečná platba neproběhla.</small>`,'success-modal','Simulace neúspěšné platby'),
'image':el=>modal(img(el.dataset.src,'Zvětšená fotografie z původního webu'),'lightbox','Galerie fotografií'),
'legal':()=>modal(`<div class="eyebrow">PREZENTAČNÍ PROTOTYP</div><h2>Informační<br>stránka.</h2><p style="margin-top:25px">V ostré verzi zde budou obchodní podmínky nebo informace o ochraně osobních údajů schválené provozovatelem. Tato vizualizace neprovozuje skutečný e-shop ani zákaznický systém.</p><p>Formuláře nic neodesílají. Demo profil, objednávky a odemčené e-booky jsou uloženy pouze v lokálním úložišti prohlížeče. Můžeš je kdykoli vymazat přes Zabezpečení účtu → Resetovat demo.</p><button class="button" data-action="close">Zpět k návrhu ↗</button>`,'','Informační stránka návrhu'),
'reset-demo':()=>modal(`<div class="eyebrow">RESET UKÁZKY</div><h2>Znovu od začátku?</h2><p style="margin-top:25px">Odstraní se pouze místní demo profil, ukázkové objednávky a odemčené e-booky.</p><div class="inline-actions"><button class="button" data-action="confirm-reset">Resetovat ukázku ↺</button><button class="button button-outline" data-action="close">Zrušit</button></div>`,'','Resetovat ukázku'),
'confirm-reset':()=>{state={cart:[],owned:[],orders:[],loggedIn:false,name:'Alex Novák',email:'alex@example.test'};save();closeModal();location.hash='library';route();toast('Ukázka je znovu ve výchozím stavu.');},
'order-detail':el=>{const o=[...state.orders,...sampleOrders].find(o=>o.id===el.dataset.id);if(!o)return;modal(`<div class="eyebrow">UKÁZKOVÁ OBJEDNÁVKA</div><h2>#${esc(o.id)}</h2><p style="margin-top:20px">${esc(o.date)} · Simulované potvrzení</p>${o.items.map(id=>{const b=findBook(id);return b?`<div class="summary-line"><span>${b.title}</span><strong>${currency(b.price)}</strong></div>`:'';}).join('')}<div class="summary-line total"><span>Celkem</span><strong>${currency(o.total)}</strong></div><p class="small-disclaimer">Nejedná se o skutečnou objednávku ani daňový doklad.</p>`,'','Detail demo objednávky');},
'admin-product':el=>adminProduct(el.dataset.id),
'admin-customer':el=>adminCustomer(el.dataset.name),
'admin-content':el=>modal(`<div class="eyebrow">NÁVRH CMS</div><h2>${esc(el.dataset.name)}</h2><form id="admin-content-form" style="margin-top:25px"><label class="field">Nadpis<input value="Mentalita šampionů." maxlength="150"></label><label class="field">Text<textarea>Za každým výsledkem je příběh. Disciplína. A tým, který tě posouvá dál.</textarea></label><p class="small-disclaimer">Ukázka editoru. Veřejný obsah ani původní web se nemění.</p><button class="button" style="margin-top:20px">Vyzkoušet uložení ↗</button></form>`,'','Návrh editoru obsahu'),
 'toggle-access':el=>{const id=el.dataset.id;if(owned(id)){state.owned=state.owned.filter(v=>v!==id);toast('Demo přístup odebrán.');}else{state.owned.push(id);toast('Demo přístup přidělen.');}save();adminCustomer(el.dataset.name);}
};
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return;}const el=e.target.closest('[data-action]');if(el){const handler=handlers[el.dataset.action];if(handler){e.preventDefault();handler(el);}}});
$('#overlay').addEventListener('click',closeModal);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('#mobile-nav').hidden=true;$('.menu-button').setAttribute('aria-expanded','false');}if((e.key==='Enter'||e.key===' ')&&e.target.matches('article[role="button"]')){e.preventDefault();product(e.target.dataset.id);}if(e.key==='Tab'&&$('.modal')){const focusables=$$('button,a[href],input,select,textarea,[tabindex="0"]',$('.modal')).filter(el=>!el.disabled&&!el.hidden);if(!focusables.length){e.preventDefault();return;}const first=focusables[0],last=focusables[focusables.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===$('.modal'))){e.preventDefault();first.focus();}}});
document.addEventListener('input',e=>{if(e.target.id==='book-search'){search=e.target.value;updateShop();}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(!f.checkValidity()){f.reportValidity();return;}if(f.id==='checkout-form')completeOrder(f);else if(f.id==='profile-form'){const d=new FormData(f);state.name=String(d.get('name')).trim()||'Alex Novák';state.email=String(d.get('email'));save();route();toast('Ukázkové údaje byly uloženy v prohlížeči.');}else if(f.id==='contact-form'){modal(`<div class="success-icon">↗</div><h2>První krok<br>máš za sebou.</h2><p style="margin-top:25px">Takto by vypadalo potvrzení poptávky. V tomto prototypu se žádné údaje neodeslaly a trenér nebyl kontaktován.</p><button class="button" data-action="close">Pokračovat v prohlížení ↗</button>`,'success-modal','Ukázka potvrzení formuláře');}else if(f.id==='register-form'){const d=new FormData(f);state.name=(d.get('first')+' '+d.get('last')).trim();state.email=String(d.get('email'));state.loggedIn=true;save();closeModal();location.hash='account';route();toast('Ukázkový profil je připravený. E-mail se neposílá.');}else if(f.id==='admin-product-form'||f.id==='admin-content-form'){closeModal();toast('Ukázka uložení dokončena. Obsah webu se nemění.');}});
window.addEventListener('hashchange',route);
route();
})();
